/**
 * P3 frontend contract test.
 *
 * Replays the canonical fixtures (generated by `smartchain_be`'s C02 checker)
 * through the **production** Zod parsers and API clients, and cross-checks the
 * generated wire artifact. No business API is mocked here on purpose: only the
 * HTTP boundary is a synthetic transport for this fixture test; the connected
 * browser run in C08 uses the real API.
 *
 * Run: node --test tests/p3-contracts.test.mjs
 */
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { after, before, test } from 'node:test';
import { fileURLToPath } from 'node:url';

import { createServer } from 'vite';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const WH = '00000000-0000-4000-8000-000000000121';
const UPDATED = '2026-11-13T00:00:00.000Z';

const fixtures = JSON.parse(
  readFileSync(new URL('./fixtures/p3-canonical-contracts.json', import.meta.url), 'utf8'),
);
const wireText = readFileSync(
  new URL('../src/features/inventory/api/p3-wire.generated.ts', import.meta.url),
  'utf8',
).replace(/\r\n/g, '\n');

let server;
let workflows;
let traceApi;
let returnApi;
let wire;
let store;
const calls = [];
let responseOverride = null;

function envelope(data) {
  return Response.json({
    success: true,
    data,
    meta: { timestamp: UPDATED, path: '/api', requestId: 'synthetic' },
  });
}

function pickResponse(method, pathname) {
  const responses = fixtures.responses;
  const rule = (pattern, methodName, data) => ({
    pattern,
    method: methodName,
    data,
  });
  const rules = [
    rule(/\/inventory-workflows\/counts$/, 'GET', responses.countPage),
    rule(/\/inventory-workflows\/counts\/options$/, 'GET', responses.countOptions),
    rule(/\/inventory-workflows\/counts$/, 'POST', responses.countPlanResult),
    rule(
      /\/inventory-workflows\/counts\/[^/]+\/observation$/,
      'POST',
      responses.countCommandResult,
    ),
    rule(/\/inventory-workflows\/putback-options$/, 'GET', responses.putbackOptions),
    rule(/\/inventory-workflows\/putbacks$/, 'GET', responses.putbackPage),
    rule(/\/inventory-workflows\/putbacks$/, 'POST', responses.putbackCommandResult),
    rule(/\/inventory-workflows\/disposals$/, 'GET', responses.disposalPage),
    rule(/\/inventory-workflows\/disposals$/, 'POST', responses.disposalCommandResult),
    rule(/\/trace\/lots\/[^/]+\/affected$/, 'GET', responses.affectedPage),
    rule(/\/trace\/lots\/[^/]+\/recall$/, 'POST', responses.recallResult),
    rule(/\/trace\/lots\/[^/]+\/notifications$/, 'POST', responses.recallNotifyResult),
    rule(/\/trace\/lots\/[^/]+$/, 'GET', responses.tracePage),
    rule(/\/trace\/parcels\/[^/]+$/, 'GET', responses.parcelTracePage),
    rule(/\/returns\/eligible$/, 'GET', responses.returnEligiblePage),
    rule(/\/returns\/bins$/, 'GET', responses.returnBins),
    rule(/\/returns$/, 'GET', responses.returnPage),
    rule(/\/returns$/, 'POST', responses.returnCommandResult),
    rule(
      /\/returns\/[^/]+\/(authorize|arrival|inspection|review|stock)$/,
      'POST',
      responses.returnCommandResult,
    ),
  ];
  const match = rules.find(
    (candidate) => candidate.method === method && candidate.pattern.test(pathname),
  );
  if (!match) throw new Error(`Unexpected API call ${method} ${pathname}`);
  return responseOverride ?? match.data;
}

before(async () => {
  server = await createServer({
    configFile: false,
    envFile: false,
    optimizeDeps: { noDiscovery: true, include: [] },
    root: ROOT,
    resolve: { alias: { '@': fileURLToPath(new URL('../src', import.meta.url)) } },
    server: { middlewareMode: true, watch: null, ws: false },
  });
  ({ inventoryWorkflowApi: workflows } = await server.ssrLoadModule(
    '/src/features/inventory/api/inventoryWorkflowApi.ts',
  ));
  ({ lotTraceApi: traceApi } = await server.ssrLoadModule(
    '/src/features/inventory/api/lotTraceApi.ts',
  ));
  ({ returnWorkflowApi: returnApi } = await server.ssrLoadModule(
    '/src/features/inventory/api/returnWorkflowApi.ts',
  ));
  ({ P3_WIRE: wire } = await server.ssrLoadModule(
    '/src/features/inventory/api/p3-wire.generated.ts',
  ));
  ({ useAuthStore: store } = await server.ssrLoadModule('/src/stores/authStore.ts'));
  store.getState().setSession({
    accessToken: 'synthetic-p3-token',
    expiresIn: 900,
    user: {
      userId: '00000000-0000-4000-8000-000000000125',
      tenantId: null,
      actorScope: 'PLATFORM',
      roles: ['OPS_DISPATCHER', 'WAREHOUSE_MANAGER', 'WAREHOUSE_STAFF'],
      permissions: [],
      email: 'synthetic@example.test',
      fullName: 'Synthetic P3 Actor',
    },
  });
  globalThis.fetch = async (input, init = {}) => {
    const url = typeof input === 'string' ? input : input.url;
    const pathname = new URL(url, 'http://127.0.0.1').pathname;
    calls.push({ method: init.method ?? 'GET', pathname, body: init.body });
    return envelope(pickResponse(init.method ?? 'GET', pathname));
  };
});

after(async () => {
  responseOverride = null;
  await server?.close();
});

test('generated wire artifact matches the canonical fixture manifest hash', () => {
  assert.equal(wire.schemaVersion, 1);
  assert.match(wire.sourceSha, /^[0-9a-f]{64}$/);
  const digest = createHash('sha256').update(wireText).digest('hex');
  assert.equal(digest, fixtures.wireSha);
  assert.equal(fixtures.sourceSha, wire.sourceSha);
  const tampered = wireText.replace('operationId: string;', 'operationId: number;');
  assert.notEqual(tampered, wireText);
  assert.notEqual(createHash('sha256').update(tampered).digest('hex'), fixtures.wireSha);
});

test('wire roots cover exactly the canonical request/response catalog', () => {
  assert.deepEqual(Object.keys(wire.roots.requests).sort(), Object.keys(fixtures.requests).sort());
  assert.deepEqual(
    Object.keys(wire.roots.responses).sort(),
    Object.keys(fixtures.responses).sort(),
  );
  for (const [category, roots] of Object.entries(wire.roots)) {
    for (const [root, typeName] of Object.entries(roots)) {
      assert.ok(wire.types[typeName], `${category}.${root} -> missing ${typeName}`);
    }
  }
  for (const typeName of Object.keys(fixtures.requests).map((root) => wire.roots.requests[root])) {
    assert.ok(wire.types[typeName], `missing request wire type ${typeName}`);
  }
});

function fieldsOf(typeName) {
  const entry = wire.types[typeName];
  assert.ok(entry, `missing wire type ${typeName}`);
  return entry.fields;
}

function checkRequestFixture(root, payload) {
  const fields = fieldsOf(wire.roots.requests[root]);
  const problems = [];
  for (const [key, field] of Object.entries(fields)) {
    if (!(key in payload)) {
      if (!field.optional) problems.push(`${root}.${key}: required key missing`);
    }
  }
  for (const key of Object.keys(payload)) {
    if (!(key in fields)) problems.push(`${root}.${key}: unknown field`);
  }
  return problems;
}

test('canonical request fixtures match the frozen request wire fields', () => {
  for (const [root, payload] of Object.entries(fixtures.requests)) {
    assert.deepEqual(checkRequestFixture(root, payload), [], `request fixture ${root}`);
  }
});

test('production API clients send exactly the canonical request payloads', async () => {
  calls.length = 0;
  await workflows.createCount(WH, fixtures.requests.countPlan);
  let call = calls.at(-1);
  assert.equal(call.method, 'POST');
  assert.match(call.pathname, /\/inventory-workflows\/counts$/);
  assert.deepEqual(JSON.parse(call.body), fixtures.requests.countPlan);

  await workflows.command(
    WH,
    `counts/${fixtures.requests.countObservation.lineId}/observation`,
    fixtures.requests.countObservation,
  );
  call = calls.at(-1);
  assert.deepEqual(JSON.parse(call.body), fixtures.requests.countObservation);

  await returnApi.command(WH, '', fixtures.requests.returnRequest);
  call = calls.at(-1);
  assert.equal(call.method, 'POST');
  assert.match(call.pathname, /\/returns$/);
  assert.deepEqual(JSON.parse(call.body), fixtures.requests.returnRequest);

  await traceApi.recall(WH, '00000000-0000-4000-8000-000000000136', fixtures.requests.recall);
  call = calls.at(-1);
  assert.deepEqual(JSON.parse(call.body), fixtures.requests.recall);

  await traceApi.notify(WH, '00000000-0000-4000-8000-000000000136', fixtures.requests.recallNotify);
  call = calls.at(-1);
  assert.deepEqual(JSON.parse(call.body), fixtures.requests.recallNotify);

  await workflows.createCount(WH, fixtures.requests.countPlan);
  for (const captured of calls) {
    const pathname = captured.pathname;
    if (pathname.endsWith('/returns')) {
      assert.equal(captured.body.includes('tenantId'), false);
      assert.equal(captured.body.includes('warehouseId'), false);
    }
  }
});

test('canonical responses parse through the production Zod schemas', async () => {
  const countPage = await workflows.counts(WH);
  assert.equal(countPage.items.length, 1);
  assert.equal(countPage.items[0].status, 'COUNTING');

  const options = await workflows.countOptions(WH);
  assert.deepEqual(options.skuCodes, ['P3-SYNTHETIC-SKU']);

  const planResult = await workflows.createCount(WH, fixtures.requests.countPlan);
  assert.equal(planResult.lineCount, 1);

  const putbackOptions = await workflows.putbackOptions(WH);
  assert.equal(putbackOptions.bins[0].zoneType, 'STORAGE');

  const putbacks = await workflows.putbacks(WH);
  assert.equal(putbacks.items[0].status, 'OPEN');

  const disposals = await workflows.disposals(WH);
  assert.equal(disposals.items[0].authorizationMode, 'CONSENT');

  const tracePage = await traceApi.trace(WH, 'lots', '00000000-0000-4000-8000-000000000136');
  assert.equal(tracePage.items[0].lotCode, 'LOT-P3-001');
  assert.equal(tracePage.items[0].picks[0].qty, 2);

  const parcelPage = await traceApi.trace(WH, 'parcels', '00000000-0000-4000-8000-000000000132');
  assert.equal(parcelPage.items[0].shipments[0].trackingNumber, 'TRACK-P3-001');

  const affected = await traceApi.affected(WH, '00000000-0000-4000-8000-000000000136');
  assert.equal(affected.items[0].name.includes('*'), true);
  assert.equal(affected.items[0].phone.includes('*'), true);

  const recall = await traceApi.recall(
    WH,
    '00000000-0000-4000-8000-000000000136',
    fixtures.requests.recall,
  );
  assert.equal(recall.status, 'RECALLED');
  assert.equal(recall.recovered ?? recall.recoveryCount, 1);

  const notified = await traceApi.notify(
    WH,
    '00000000-0000-4000-8000-000000000136',
    fixtures.requests.recallNotify,
  );
  assert.equal(notified.queued, 1);

  const returnList = await returnApi.list(WH);
  assert.equal(returnList.items[0].status, 'ARRIVED');

  const eligible = await returnApi.eligible(WH);
  assert.equal(eligible.items[0].remainingQty, 1);

  const bins = await returnApi.bins(WH);
  assert.equal(bins.truncated, false);

  const command = await returnApi.command(WH, '', fixtures.requests.returnRequest);
  assert.equal(command.status, 'ARRIVED');
});

test('staff blind count projection never carries manager-only keys', async () => {
  const staffPage = {
    items: [
      {
        ...fixtures.responses.countPage.items[0],
        lines: [fixtures.privacy.staffBlindCountLine],
      },
    ],
    nextCursor: null,
  };
  responseOverride = staffPage;
  const parsed = await workflows.counts(WH);
  responseOverride = null;
  const line = parsed.items[0].lines[0];
  assert.equal(Object.hasOwn(line, 'expectedQty'), false);
  assert.equal(Object.hasOwn(line, 'varianceQty'), false);
  assert.equal(Object.hasOwn(line, 'variancePercent'), false);
  const managerLine = fixtures.responses.countPage.items[0].lines[0];
  assert.equal(managerLine.expectedQty, 2);
  assert.equal(managerLine.varianceQty, -2);
  const lineFields = fieldsOf('CountPageViewItemsItemLinesItem');
  assert.equal(lineFields.expectedQty?.optional, true);
  assert.equal(lineFields.varianceQty?.optional, true);
  assert.equal(lineFields.variancePercent?.optional, true);
});

test('production parsers reject malformed server payloads instead of trusting them', async () => {
  const malformed = [
    {
      ...fixtures.responses.countPage,
      items: [{ ...fixtures.responses.countPage.items[0], id: undefined }],
    },
    {
      ...fixtures.responses.countPage,
      items: [
        {
          ...fixtures.responses.countPage.items[0],
          lines: [{ ...fixtures.responses.countPage.items[0].lines[0], unexpectedField: 1 }],
        },
      ],
    },
    { ...fixtures.responses.countOptions, skuCodes: undefined },
    {
      ...fixtures.responses.tracePage,
      items: [{ ...fixtures.responses.tracePage.items[0], lotCode: 42 }],
    },
  ];
  for (const payload of malformed) {
    responseOverride = payload;
    let rejected = false;
    try {
      if (payload.skuCodes === undefined) await workflows.countOptions(WH);
      else if (payload === malformed[3]) {
        await traceApi.trace(WH, 'lots', '00000000-0000-4000-8000-000000000136');
      } else await workflows.counts(WH);
    } catch {
      rejected = true;
    }
    responseOverride = null;
    assert.equal(rejected, true, 'malformed payload must fail the production parser');
  }
});

test('recall CSV export neutralizes spreadsheet formulas and masks contact data', async () => {
  const rows = [
    {
      id: '00000000-0000-4000-8000-000000000133',
      orderId: '00000000-0000-4000-8000-000000000140',
      parcelId: '00000000-0000-4000-8000-000000000132',
      name: '=HYPERLINK("http://evil.test")',
      phone: '*********01',
      qty: 1,
    },
  ];
  const { recallCsv } = await server.ssrLoadModule('/src/features/inventory/api/lotTraceApi.ts');
  const csv = recallCsv(rows);
  assert.match(csv, /"'=HYPERLINK/);
  assert.equal(csv.includes('*********01'), true);
  assert.equal(csv.includes(fixtures.privacy.piiCanary), false);
});

test('canonical fixtures never contain the PII canary or raw contact data', () => {
  const serialized = JSON.stringify({
    requests: fixtures.requests,
    responses: fixtures.responses,
  });
  assert.equal(serialized.includes(fixtures.privacy.piiCanary), false);
  const affected = fixtures.responses.affectedPage.items[0];
  assert.equal(affected.name, 'S***');
  assert.equal(affected.phone, fixtures.privacy.maskedPhoneCanary);
});
